                  className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                    currentEventId === id ? `${themeClasses.bg} text-white` : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                  }`}
                >
                  {EVENT_CONFIGS[id].name}
                </button>
