            </div>
          </div>
        </div>
        {/* Four Column Layout */}
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">

          {/* Left Sidebar - Event Details and Rules */}
          <div className="space-y-6">
            {/* Event Details */}
            <div className="bg-white rounded-xl shadow-xl p-6">
